def pair13_predecessor(base, binding, actual, owner):
    transition = PAIR13_TRANSITION
    base.need(same_json(binding.get('pair13_transition'), transition), 'Pair13 typed transition differs')
    base.need(len(actual) == transition['sourceCountAfter'] and owner.source_digest(actual) == transition['sourceAfter'], 'Pair13 current source differs')
    base.need(same_json(owner.load_profile(ROOT), transition['profileAfter']), 'Pair13 exact profile differs')
    predecessor = dict(actual)
    for row in transition['owningChanges']:
        base.need(same_json(actual.get(row['path']), row['after']), 'Pair13 current owning row differs')
        if row['before'] is None:
            del predecessor[row['path']]
        else:
            predecessor[row['path']] = row['before']
    base.need(len(predecessor) == transition['sourceCountBefore'] and owner.source_digest(predecessor) == transition['sourceBefore'], 'Pair13 predecessor source differs')
    return predecessor

def pair13_predecessor_raw(base, path):
    raw = base.regular(path).read_bytes()
    relative = path.relative_to(ROOT).as_posix()
    row = next(r for r in PAIR13_TRANSITION['rawPredecessors'] if r['path'] == relative)
    base.need({'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()} == row['after'], 'Pair13 exact raw successor differs')
    old = raw.decode()
    for edit in reversed(row['edits']):
        old = old.replace(edit['after'], edit['before'])
    old = old.encode()
    base.need({'bytes':len(old),'sha256':hashlib.sha256(old).hexdigest()} == row['before'], 'Pair13 exact raw predecessor differs')
    return old


